modelica_source:
model Baseline
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing;
end Baseline;
model BUG015
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(shaft(J=0));
end BUG015;
model BUG016
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(housing(J=0));
end BUG016;
model BUG026
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(idealGear(ratio=0));
end BUG026;
model FinalBUG015
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(shaft(final J=0));
end FinalBUG015;
model FinalBUG016
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(housing(final J=0));
end FinalBUG016;
model FinalBUG026
  extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(idealGear(final ratio=0));
end FinalBUG026;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG015\n");
simulate(BUG015, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG016\n");
simulate(BUG016, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG026\n");
simulate(BUG026, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG015\n");
simulate(FinalBUG015, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG016\n");
simulate(FinalBUG016, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG026\n");
simulate(FinalBUG026, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG015\n");
system("./Baseline -override shaft.J=0 -r=BUG015_override.csv");
print("AUDIT_OVERRIDE BUG016\n");
system("./Baseline -override housing.J=0 -r=BUG016_override.csv");
print("AUDIT_OVERRIDE BUG026\n");
system("./Baseline -override idealGear.ratio=0 -r=BUG026_override.csv");
